	if err != nil {
		return fmt.Errorf("load session state: %w", err)
	}
	if state == nil {
		return ErrStateNotFound
	}
	gate.activeState = state
	defer func() { gate.activeState = nil }()

	if err := fn(state); err != nil {
		if errors.Is(err, ErrMutationSkip) {
			return nil
		}
		return err
